from pathlib import Path
from playwright.sync_api import sync_playwright,expect
import json,re,argparse,shutil
from urllib.parse import urlparse
parser=argparse.ArgumentParser(description="Browser regression of the self-contained ncLEANEK floating demo")
parser.add_argument("--url",required=True)
parser.add_argument("--html",type=Path,required=True)
parser.add_argument("--output",type=Path,default=Path("/tmp/ncleanek-floating-preview-test"))
parser.add_argument("--chromium",default=shutil.which("chromium"))
args=parser.parse_args()
if urlparse(args.url).hostname not in ("127.0.0.1","localhost"):parser.error("Serve the synthetic preview locally.")
args.output.mkdir(parents=True,exist_ok=True)
out=args.output
with sync_playwright()as p:
 b=p.chromium.launch(executable_path=args.chromium,headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':900});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(args.url);frame=page.frame_locator('#screen');actor=frame.locator('.ncleanek-launch');dock=frame.locator('.ncleanek-dock');panel=frame.locator('#ncleanek-panel');expect(actor).to_be_visible();actor.click();expect(panel.locator('.ncleanek-step')).to_contain_text('1 z ');page.keyboard.press('Escape');page.wait_for_timeout(200);r=actor.bounding_box();page.mouse.move(r['x']+25,r['y']+30);page.mouse.down();page.mouse.move(90,240,steps=10);expect(dock).to_have_class(re.compile('.*is-dragging.*'));page.mouse.up();expect(panel).not_to_be_visible();page.locator('#preview-route').select_option('/dashboard');expect(actor).to_be_visible();assert page.frame(name='screen').evaluate("localStorage.getItem('nclean.puppet.position.v1')")is not None;frame.get_by_role('link',name='Więcej',exact=True).click();frame.get_by_role('link',name='Ustawienia',exact=False).click();frame.get_by_text('Wygląd i aplikacja',exact=True).click();frame.locator('[data-ncleanek-position-reset]').click();assert page.frame(name='screen').evaluate("localStorage.getItem('nclean.puppet.position.v1')")is None;page.locator('#preview-route').select_option('/calendar');frame.locator('.add-booking').click();form=frame.locator('#booking-form');form.locator('[data-category-choice="1"]').click();form.locator('[name=qty_2]').fill('1');form.locator('[name=name]').fill('Klient próbnego podglądu');form.locator('[name=phone]').fill('500000099');form.locator('[name=address]').fill('Syntetyczny adres');expect(actor).to_be_visible();actor.click();expect(panel.locator('.ncleanek-step')).to_contain_text('1 z ');page.keyboard.press('Escape');expect(form.locator('[name=address]')).to_have_value('Syntetyczny adres');form.get_by_role('button',name='Zapisz zlecenie',exact=True).click();expect(frame.locator('#booking-editor')).not_to_be_visible();expect(frame.locator('#agenda-orders')).to_contain_text('Klient próbnego podglądu');page.set_viewport_size({'width':390,'height':844});page.screenshot(path=str(out/'demo-390.png'));assert not errors,errors;b.close()
 b=p.chromium.launch(executable_path=args.chromium,headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.on('pageerror',lambda e:errors.append(str(e)));page.set_content('<iframe id="chat" name="chat" sandbox="allow-scripts" style="width:100%;height:810px;border:0"></iframe>');page.locator('#chat').evaluate('(e,s)=>{e.srcdoc=s;}',args.html.read_text());f=page.frame_locator('#chat').frame_locator('#screen');expect(f.locator('.ncleanek-launch')).to_be_visible();f.locator('.ncleanek-launch').click();expect(f.locator('#ncleanek-panel .ncleanek-step')).to_contain_text('1 z ');page.keyboard.press('Escape');f.get_by_role('link',name='Klienci',exact=True).click();expect(f.locator('h1')).to_have_text('Klienci');assert not errors,errors;b.close();(out/'preview-results.json').write_text(json.dumps({'floating_drag':True,'position_between_routes':True,'reset':True,'booking_after_form_tour':True,'nested_sandbox':True,'javascript_errors':errors},indent=2));print('PASS floating preview: drag, contextual tours, position/reset across routes, booking, nested sandbox; no JS errors.')
